 const src=[...document.scripts].map(s=>s.textContent).join('\n');const i0=src.indexOf('const DATA=');const j0=src.indexOf('\n',i0);const code=(src.slice(0,i0)+src.slice(j0)).replace(/\/\*P0D_INI\*\/[\s\S]*\/\*P0D_FIN\*\//,'');
 const unesc=s=>s.replace(/\\(u[0-9a-fA-F]{4}|x[0-9a-fA-F]{2}|[\s\S])/g,(m,c)=>c[0]==='u'||c[0]==='x'&&c.length==3?String.fromCharCode(parseInt(c.slice(1),16)):({n:'\n',t:'\t',r:'\r',b:'\b',f:'\f',v:'\v',0:'\0'}[c]??c));
 const norm=s=>{let o='',i=0;while(i<s.length){if(s[i]==='$'&&s[i+1]==='{'){let d=1,j=i+2;while(j<s.length&&d){if(s[j]==='{')d++;else if(s[j]==='}')d--;j++;}o+='{}';i=j;}else{o+=s[i];i++;}}return o.replace(/\{\w+\}/g,'{}');};
 const vals=new Set();const walk=o=>{if(typeof o==='string')vals.add(norm(o));else if(Array.isArray(o))o.forEach(walk);else if(o&&typeof o==='object')Object.values(o).forEach(walk);};walk(DATA);
 const blob='\0'+[...vals].join('\0')+'\0';
